-- Guia "Atacama em 4 dias: altitude, ingressos e passeios do mais baixo ao mais alto" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/atacama-em-4-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('617d36bf-8af3-4fe6-a16c-cc359875c677', 'atacama-em-4-dias', 'draft', 'america-do-sul', 'Atacama em 4 dias: altitude, ingressos e passeios do mais baixo ao mais alto', 'do mais baixo ao mais alto', 'Roteiro de San Pedro de Atacama em 4 dias com Valle de la Luna, lagunas e Géiseres del Tatio, o cuidado com a altitude e o frio, documentos, valores em pesos chilenos e em reais e o guia em PDF para baixar de graça.', 'San Pedro fica a cerca de 2.400 metros, e dois passeios passam de 4.000. O roteiro vai do mais baixo ao mais alto, para o corpo ter tempo, e o guia completo vai no celular.', 'San Pedro de Atacama', NULL, '/assets/blog/atacama-4-dias.jpg', '/assets/blog/atacama-4-dias-m.jpg', 'Sol baixo e alaranjado se pondo atrás das formações rochosas escuras do Valle de la Luna, no deserto do Atacama', 0, '[{"t":"pdf","href":"/guias/atacama-em-4-dias.pdf","note":"PDF de 17 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"San Pedro de Atacama fica a cerca de 2.400 m (estimativa de blog de viagem, não dado oficial), e **os dois passeios mais altos passam de 4.000 m**. Por isso este roteiro vai do mais baixo para o mais alto: a chegada tranquila, o Valle de la Luna, as lagunas e, no fim, os géiseres do Tatio. San Pedro é a base, chegando por Calama."},{"t":"tip","items":["**Reserve o Valle de la Luna e as lagunas antes:** os acessos são regulados.","**Leve casaco:** no Tatio, de madrugada, faz muito frio.","**Beba água e vá devagar nos dois primeiros dias.**"],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Chegada e a vila","label":"Dia 1"},{"t":"p","text":"Voo até Calama, traslado até San Pedro e uma tarde tranquila para o corpo se acostumar."},{"t":"img","src":"/assets/blog/atacama-san-pedro.jpg","alt":"Rua de terra de San Pedro de Atacama, com casas baixas de adobe caiadas e uma pessoa de boné vermelho caminhando","caption":"Uma rua de San Pedro de Atacama.","credit":"Foto: Cristian Salinas Cisternas / Pexels","w":870,"h":580},{"t":"ul","items":["**Chegada, aeroporto de Calama:** o aeroporto de El Loa, em Calama, é o mais próximo. Combine o traslado antes: a viagem até San Pedro leva cerca de 1 hora a 1h30. Conte de 2 a 3 horas entre o pouso e o hotel.","**Tarde, a vila de San Pedro:** casas baixas de adobe, ruas de terra e as agências de passeio na Calle Caracoles. Bom lugar para conferir reservas e comprar água.","**Noite, durma cedo:** os passeios dos próximos dias saem cedo, e dormir mal piora os sintomas da altitude."]},{"t":"tip","items":["A altitude pega mais forte nas primeiras horas. Beba água, evite álcool e refeição pesada, e deixe os passeios altos para o fim.","**Chegue com os ingressos do Dia 2 e do Dia 3 já comprados:** os acessos são regulados. É uma dica da Rota Certa."],"title":"Não marque passeio alto no primeiro dia"},{"t":"tip","items":["**Grátis:** caminhar pela vila e pela Calle Caracoles. **Opcional:** reservar os passeios dos próximos dias.","**Estimativa da Rota Certa, não é dado oficial:** a vila se faz a pé, sem pressa. Esforço baixo, de propósito."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a Calle Caracoles no Google Maps](https://www.google.com/maps/search/?api=1&query=Calle%20Caracoles%2C%20San%20Pedro%20de%20Atacama)"},{"t":"passeio","busca":"San Pedro de Atacama traslado Calama","title":"Traslados e passeios em San Pedro"},{"t":"h","text":"Valle de la Luna","label":"Dia 2"},{"t":"p","text":"Rochas esculpidas pelo vento, dunas e o pôr do sol mais famoso do deserto."},{"t":"img","src":"/assets/blog/atacama-valle-de-la-luna.jpg","alt":"Paisagem de rochas erodidas e vales secos do Valle de la Luna, vista do alto, sob um céu de nuvens","caption":"O Valle de la Luna, visto de um mirante.","credit":"Foto: Eleanore Stohner / Pexels","w":1000,"h":662},{"t":"ul","items":["**Manhã, livre e leve:** descanse, passeie pela vila e confira os horários do passeio da tarde. Ainda é cedo para esforço.","**Tarde, Valle de la Luna:** a reserva fica perto da vila. Entre com tempo para ver os mirantes e as trilhas curtas, sem correr.","**Fim da tarde, pôr do sol:** é o horário mais disputado. Confira a hora em que o parque fecha no dia: ela muda com a estação."]},{"t":"tip","items":["**Preço e horário da bilheteria online:** CLP 10.800 (cerca de R$ 60) e, no inverno, das 9h às 17h. Confirme no site antes de comprar.","A entrada é vendida online e é ao portador. Quem não vai com agência precisa entrar de carro particular. Drones, bebida alcoólica e pets são proibidos."],"title":"Compre o ingresso online, por data"},{"t":"tip","items":["**Leve casaco:** quando o sol se põe no deserto, a temperatura cai rápido. É uma dica da Rota Certa.","**Leve:** água, chapéu, óculos e protetor solar. **Opcional:** tour de pôr do sol com agência.","**Estimativa da Rota Certa, não é dado oficial:** esforço baixo a moderado."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir o Valle de la Luna no Google Maps](https://www.google.com/maps/search/?api=1&query=Valle%20de%20la%20Luna%2C%20San%20Pedro%20de%20Atacama)"},{"t":"passeio","busca":"Valle de la Luna San Pedro de Atacama","title":"Passeios ao Valle de la Luna"},{"t":"h","text":"Lagunas Altiplânicas","label":"Dia 3"},{"t":"p","text":"Lagoas azuis e vulcões a mais de 4.100 m, pela Ruta 23, passando por Toconao e Socaire."},{"t":"img","src":"/assets/blog/atacama-lagunas.jpg","alt":"Laguna Miscanti, de águas azuis, cercada por montanhas áridas cor de areia e um céu azul sem nuvens","caption":"A Laguna Miscanti.","credit":"Foto: Éder Prado / Pexels","w":1000,"h":563},{"t":"ul","items":["**Manhã, Ruta 23 até as lagunas:** a estrada passa por Toconao e Socaire, rumo ao sul. Saia cedo e tome um café da manhã leve antes de subir.","**Meio-dia, Miscanti e Miñiques:** duas lagunas de águas azuis cercadas de vulcões. A reserva é só para visita de dia. Fique no mirante e caminhe devagar: a altitude cansa.","**Volta, Laguna Chaxa (opcional):** no Salar de Atacama, é onde dá para ver flamingos. Fica na Reserva Los Flamencos, que tem acessos e cobrança por setor. Veja se cabe no horário."]},{"t":"tip","items":["A entrada é obrigatória e deve ser comprada com antecedência. O turismo oficial do Chile recomenda carro 4x4 e passeio guiado.","Em época de neve, o acesso pode fechar (informação de operador: confirme).","**Valor oficial do ingresso das lagunas e de Chaxa:** não encontrado. Confirme na compra."],"title":"Compre o ingresso antes e confirme a estrada"},{"t":"img","src":"/assets/blog/atacama-chaxa.jpg","alt":"Flamingos na Laguna Chaxa, refletidos na água calma e rasa, com uma montanha distante no horizonte","caption":"Flamingos na Laguna Chaxa, no Salar de Atacama.","credit":"Foto: Willian Justen de Vasconcellos / Pexels","w":1000,"h":667},{"t":"tip","items":["**Leve água de sobra, chapéu e óculos com filtro UV:** o sol é forte e o ar é seco. É uma dica da Rota Certa.","**Distância e altitude:** cerca de 115 km de San Pedro, cerca de 2 h de carro, a mais de 4.100 m (turismo oficial do Chile, atualizado em 9/2/2026).","**Estimativa da Rota Certa, não é dado oficial:** esforço moderado, por causa da altitude, não da caminhada."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir as lagunas no Google Maps](https://www.google.com/maps/search/?api=1&query=Lagunas%20Altipl%C3%A1nicas%2C%20Miscanti%2C%20Chile)"},{"t":"passeio","busca":"Lagunas Altiplânicas Miscanti San Pedro de Atacama","title":"Passeios às lagunas"},{"t":"h","text":"Géiseres del Tatio","label":"Dia 4"},{"t":"p","text":"Vapor subindo no nascer do sol, a mais de 4.300 m, e depois o caminho de volta a Calama."},{"t":"img","src":"/assets/blog/atacama-tatio.jpg","alt":"Colunas de vapor dos Géiseres del Tatio ao amanhecer, refletidas na água, com montanhas ao fundo","caption":"Os Géiseres del Tatio.","credit":"Foto: Marek Piwnicki / Pexels","w":1000,"h":563},{"t":"ul","items":["**Madrugada, saída de San Pedro:** os passeios costumam sair entre 4h e 5h. A estrada é de terra e o trecho final é frio e escuro. Vá com a agência, se não conhece o caminho.","**Nascer do sol, os géiseres:** o melhor momento é entre 6h e 7h, quando as colunas de vapor aparecem mais. O parque abre às 6h e fecha às 16h30. Pagamento na entrada.","**Manhã, volta e traslado:** descanse, faça as malas e siga para o aeroporto de Calama. Marque o voo para o fim do dia: a volta do Tatio pode atrasar."]},{"t":"tip","items":["**Frio:** chega a cerca de -20 °C. Use camadas, luvas, gorro e leve um lanche. Ao meio-dia já dá para tirar o casaco.","**Ingresso:** CLP 15.000 (cerca de R$ 83), valor de reportagem de 2025. Confirme com a agência. Pode ser pago em dinheiro na entrada: leve pesos chilenos em espécie.","**Menores de idade, confirme a regra:** uma fonte diz que menores de 8 anos não pagam, e um operador diz que só entram crianças a partir de 9 anos. Pergunte à agência antes de levar crianças."],"title":"Frio, ingresso e menores"},{"t":"tip","items":["**Distância:** cerca de 80 km, 1h30 de carro, estrada de terra (turismo oficial do Chile, atualizado em 9/2/2026).","**Opcional:** voo para casa só no fim do dia. É uma estimativa da Rota Certa."],"title":"Para planejar o Dia 4"},{"t":"p","text":"[Abrir o Tatio no Google Maps](https://www.google.com/maps/search/?api=1&query=G%C3%A9iseres%20del%20Tatio%2C%20Chile)"},{"t":"passeio","busca":"Géiseres del Tatio San Pedro de Atacama","title":"Passeios aos Géiseres del Tatio"},{"t":"h","text":"Altitude e frio","label":"Saúde"},{"t":"ul","items":["**Os dois passeios mais altos ficam no fim:** as lagunas passam de 4.100 m e o Tatio de 4.300 m. Por isso este roteiro vai do mais baixo para o mais alto.","**Para o corpo se acostumar:** beba muita água, coma leve, evite álcool nas primeiras horas e durma bem. Chá de coca é comum nos hotéis. Se doer a cabeça ou der enjoo, descanse e desça de altitude.","**Converse com um médico antes:** quem tem problema no coração, pressão alta não controlada, doença respiratória, gravidez ou anemia grave deve conversar com o médico antes de ir. O seguro viagem é recomendado.","**Quatro dias é apertado:** se puder, some um dia livre no começo."]},{"t":"p","text":"A altitude da vila e as dicas de aclimatação vêm de guias de viagem, não de fonte oficial. A altitude e o frio dos passeios vêm do turismo oficial do Chile."},{"t":"h","text":"Documentos, como chegar e dinheiro","label":"Antes de ir"},{"t":"ul","items":["**RG com menos de 10 anos:** brasileiro entra no Chile como turista com passaporte válido ou com o RG, se ele estiver em bom estado e tiver sido emitido há menos de 10 anos. CNH e identidade só no celular não valem.","**Até 90 dias, sem visto:** na chegada, podem pedir comprovante de meios para a estada e passagem de volta. Guarde o comprovante de entrada até sair do país.","**Passaporte é o mais seguro:** o Itamaraty recomenda o passaporte, principalmente para quem faz conexão. A conexão em Santiago é a mais comum para chegar a Calama.","**Como chegar do Brasil:** o aeroporto mais próximo é o de El Loa, em Calama, a cerca de 1 hora de San Pedro. A rota comum é voar até Santiago e seguir em voo doméstico até Calama (confirme com a companhia). A Rota Certa cota o trecho completo.","**De Calama a San Pedro:** há traslado compartilhado e privado. Agências pedem reserva com antecedência (mínimo de 48 horas em uma delas). Horários e preços do ônibus público: confirme com as empresas.","**Tomada e voltagem:** o Chile usa 220 V e tomadas dos tipos C e L, de pinos redondos. Plugue brasileiro de três pinos não encaixa: leve adaptador."]},{"t":"p","text":"As regras do Consulado do Brasil em Santiago foram conferidas em 14/10/2026. A página bloqueou o acesso automático em 27/10: confirme no site antes de ir."},{"t":"tip","items":["RG emitido há menos de 10 anos ou passaporte.","Passagem de volta.","Valle de la Luna e lagunas reservados.","Seguro viagem com cobertura médica.","Casaco, luvas e gorro, mesmo no verão.","Protetor solar, chapéu e óculos com filtro UV.","Adaptador de tomada."],"title":"Checklist"},{"t":"tip","items":["Valle de la Luna (CLP 10.800) e Tatio (CLP 15.000) somam CLP 25.800 (cerca de R$ 143) por adulto, sem contar o transporte do passeio.","Reais pela cotação de venda do Banco Central de 26/10/2026 (CLP 1.000 = R$ 5,54). No cartão entram o IOF e o câmbio do seu banco."],"title":"Quanto custa"},{"t":"pdf","href":"/guias/atacama-em-4-dias.pdf","note":"Leve o roteiro, o mapa dos passeios e o orçamento no celular. Grátis, sem cadastro."},{"t":"tip","items":["**Entrada com RG:** [Consulado do Brasil em Santiago](https://www.gov.br/mre/pt-br/consulado-santiago/condicoes-de-viagem/documentos-para-ingresso-no-chile).","**Turismo oficial do Chile:** [Géiseres del Tatio](https://chile.travel/atractivos/geiseres-del-tatio/), [Lagunas Altiplânicas](https://chile.travel/atractivos/lagunas-altiplanicas/) e [Reserva Los Flamencos](https://chile.travel/?p=61568).","**Preços:** [Valle de la Luna, bilheteria Puntoticket](https://www.puntoticket.com/valle-de-la-luna) e [Tatio, reportagem do Meteored](https://www.meteored.cl/noticias/actualidad/el-campo-de-geiseres-mas-grande-del-hemisferio-sur-te-espera-a-2-horas-de-calama.html).","**Altitude e aclimatação:** [Dicas Chile (blog)](https://dicaschile.com.br/san-pedro-de-atacama/altitudes-dos-passeios-em-san-pedro-do-atacama-e-como-se-preparar/).","**Outras:** [tomadas, IEC](https://www.iec.ch/world-plugs) e [câmbio, Banco Central](https://www4.bcb.gov.br/Download/fechamento/20261026.csv)."],"title":"Fontes consultadas, conferidas em 27/10/2026"},{"t":"tip","items":["**Preço e regras oficiais do Valle de la Luna** e o **preço atual do Tatio:** os valores vêm da bilheteria online e de reportagem. Confirme na compra.","**Ingressos das lagunas, de Chaxa e do Salar** (Cejar, Tebinquiche): valor oficial não encontrado.","**Idade mínima no Tatio:** as fontes divergem. Pergunte à agência.","**Fechamento das lagunas por neve:** só a informação de um operador.","**Voos de Santiago a Calama** e **ônibus público de Calama a San Pedro:** confirme horários e preços com as empresas.","**Altitude oficial de San Pedro:** o guia usa estimativa de blog de viagem."],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. O que não achamos em fonte oficial está marcado como \"confirme\". As estimativas de tempo e esforço e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Csaba Marosi / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 9);
